getstr(struct magic_set *ms, struct magic *m, const char *s, int warn)
{
        const char *origs = s;
        char    *p = m->value.s;
        size_t  plen = sizeof(m->value.s);
        char    *origp = p;
        char    *pmax = p + plen - 1;
        int     c;
        int     val;
        size_t  bracket_nesting = 0;

        while ((c = *s++) != '\0') {
                if (isspace(CAST(unsigned char, c)))
                        break;
                if (p >= pmax) {
                        file_error(ms, 0, "string too long: `%s'", origs);
                        return NULL;
                }
                if (c != '\\') {
                    if (c == '[') {
                            bracket_nesting++;
                    }
                    if (c == ']' && bracket_nesting > 0) {
                            bracket_nesting--;
                    }
                    *p++ = CAST(char, c);
                    continue;
                }
                switch(c = *s++) {

                case '\0':
                        if (warn)
                                file_magwarn(ms, "incomplete escape");
                        s--;
                        goto out;
                case '.':
                        if (m->type == FILE_REGEX &&
                            bracket_nesting == 0 && warn) {
                                file_magwarn(ms, "escaped dot ('.') found, "
                                    "use \\\\. instead");
                        }
                        warn = 0; /* already did */
                        /*FALLTHROUGH*/
                case '\t':
                        if (warn) {
                                file_magwarn(ms,
                                    "escaped tab found, use \\\\t instead");
                                warn = 0;       /* already did */
                        }
                        /*FALLTHROUGH*/
                default:
                        if (warn) {
                                if (isprint(CAST(unsigned char, c))) {
                                        /* Allow escaping of
                                         * ``relations'' */
                                        if (strchr("<>&^=!", c) == NULL
                                            && (m->type != FILE_REGEX ||
                                            strchr("[]().*?^$|{}", c)
                                            == NULL)) {
                                                file_magwarn(ms, "no "
                                                    "need to escape "
                                                    "`%c'", c);
                                        }
                                } else {
                                        file_magwarn(ms,
                                            "unknown escape sequence: "
                                            "\\%03o", c);
                                }
                        }
